// CDP probe for the document previewer matrix (`pages/document-viewer/index.tsx`
// + `components/document-preview/*`): one document per file type is uploaded, then
// the real page is driven in Chrome — the extension picks the previewer, the
// previewer fetches the bytes from the page's own byte source
// (`resource=document` → `/api/v1/documents/{id}/preview`, `resource=files` →
// `/api/v1/files/{id}`) and renders into the container upstream's component fills.
//
// Fixtures are generated by the caller (see the `RAYRAG_PREVIEW_FIXTURES`
// directory: notes.txt, notes.md, table.csv, pixel.png, book.xlsx, deck.pptx,
// legacy.docx). Nothing is written into the repository.
//
// Usage: RAYRAG_CDP_ORIGIN=http://127.0.0.1:9390 \
//        RAYRAG_LOGIN_PASSWORD=... \
//        node scripts/ui-traversal/document-preview-matrix-cdp.mjs
import { chromium } from "playwright-core";
import { mkdirSync, readFileSync } from "node:fs";
import { basename, join } from "node:path";

const ORIGIN = process.env.RAYRAG_CDP_ORIGIN || "http://127.0.0.1:9390";
const PASSWORD = process.env.RAYRAG_LOGIN_PASSWORD;
const FIXTURES = process.env.RAYRAG_PREVIEW_FIXTURES || "/tmp/rr-preview-fixtures";
if (!PASSWORD) {
  console.error(
    "RAYRAG_LOGIN_PASSWORD is required (sourced from operator env, not committed)",
  );
  process.exit(2);
}
const STAMP = Date.now();
const DATASET = `cdp-preview-matrix-${STAMP}`;
const shots = "docs/ui-traversal/rayrag-audit";
mkdirSync(shots, { recursive: true });

const read = (name) => Array.from(readFileSync(join(FIXTURES, name)));

const b = await chromium.connectOverCDP("http://127.0.0.1:16002");
const ctx = b.contexts()[0];
const page = await ctx.newPage();
await page.setViewportSize({ width: 1440, height: 1000 });
const pageErrors = [];
page.on("pageerror", (error) => pageErrors.push(String(error.message)));
const results = { steps: [], errors: [], pageErrors };
const step = (name, value) => {
  results.steps.push({ name, value });
  console.log(`• ${name}: ${JSON.stringify(value)}`);
};
const fail = (message) => {
  throw new Error(message);
};

let datasetId = null;
try {
  await ctx.addCookies([{ name: "lang", value: "en", domain: "127.0.0.1", path: "/" }]);
  await page.goto(ORIGIN + "/login", { waitUntil: "domcontentloaded", timeout: 40000 });

  const files = {};
  for (const name of [
    "notes.txt",
    "notes.md",
    "table.csv",
    "pixel.png",
    "book.xlsx",
    "deck.pptx",
    "legacy.docx",
  ]) {
    files[name] = read(name);
  }

  const seeded = await page.evaluate(
    async ({ password, name, fixtures }) => {
      const login = await fetch("/api/v1/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email: "admin@rayrag.local", password }),
      }).then((res) => res.json());
      if (!login.data?.access_token) throw new Error("login failed");
      const token = login.data.access_token;
      localStorage.setItem("rayrag_token", token);
      document.cookie = `rayrag_token=${token};path=/`;
      const kb = await fetch("/api/v1/datasets", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name, chunk_method: "naive" }),
      }).then((res) => res.json());
      const datasetId = kb.data.id;
      const ids = {};
      for (const [fileName, bytes] of Object.entries(fixtures)) {
        const form = new FormData();
        form.append("file", new Blob([new Uint8Array(bytes)]), fileName);
        const uploaded = await fetch(`/api/v1/datasets/${datasetId}/documents`, {
          method: "POST",
          body: form,
        }).then((res) => res.json());
        if (uploaded.code !== 0) throw new Error(`${fileName}: ${uploaded.message}`);
        ids[fileName] = uploaded.data.id;
      }
      // Files-page uploads: the txt one exercises the `resource=files` byte source
      // (txt has a previewer but no Eye button), the png one carries the Eye button
      // (`SupportedPreviewDocumentTypes`).
      const fileIds = {};
      for (const fileName of ["notes.txt", "pixel.png"]) {
        const single = new FormData();
        single.append("file", new Blob([new Uint8Array(fixtures[fileName])]), `shared-${fileName}`);
        const fileRecord = await fetch("/api/v1/files/upload", {
          method: "POST",
          body: single,
        }).then((res) => res.json());
        if (fileRecord.code !== 0) throw new Error(`file upload ${fileName}: ${fileRecord.message}`);
        fileIds[fileName] = fileRecord.data.id;
      }
      return {
        datasetId,
        ids,
        fileId: fileIds["notes.txt"],
        imageFileId: fileIds["pixel.png"],
        token,
      };
    },
    { password: PASSWORD, name: DATASET, fixtures: files },
  );
  datasetId = seeded.datasetId;
  step("seeded dataset", { datasetId, documents: Object.keys(seeded.ids).length });

  const expect = async (documentId, ext, check) => {
    await page.goto(`${ORIGIN}/document/${documentId}?ext=${ext}`, {
      waitUntil: "domcontentloaded",
      timeout: 40000,
    });
    const value = await check();
    return value;
  };

  // 1. txt: `TxtPreviewer` fetches the text into the <pre>.
  results.txt = await expect(seeded.ids["notes.txt"], "txt", async () => {
    await page.waitForFunction(
      () => (document.getElementById("dpText")?.textContent || "").includes("preview probe"),
      null,
      { timeout: 30000 },
    );
    return page.evaluate(() => ({
      kind: document.querySelector("[data-testid='docpreview-section']").dataset.kind,
      text: document.getElementById("dpText").textContent.trim(),
      spinner: document.getElementById("dpSpin").hidden,
    }));
  });
  if (results.txt.kind !== "txt") fail("txt selected the wrong previewer");
  step("txt previewer", results.txt);
  await page.screenshot({ path: `${shots}/preview-matrix-txt-${STAMP}.png` });

  // 2. markdown: `Md` renders GFM + hard breaks through the shared renderer.
  results.md = await expect(seeded.ids["notes.md"], "md", async () => {
    await page.waitForFunction(
      () => !!document.querySelector("#dpMarkdown h1"),
      null,
      { timeout: 30000 },
    );
    return page.evaluate(() => ({
      heading: document.querySelector("#dpMarkdown h1")?.textContent,
      bold: !!document.querySelector("#dpMarkdown strong"),
      link: document.querySelector("#dpMarkdown a")?.getAttribute("href"),
      table: document.querySelectorAll("#dpMarkdown table.md-table tbody tr").length,
      list: document.querySelectorAll("#dpMarkdown ul li").length,
      code: document.querySelector("#dpMarkdown pre.md-code code")?.textContent.trim(),
      quote: document.querySelector("#dpMarkdown blockquote")?.textContent.trim(),
    }));
  });
  if (results.md.heading !== "Heading One") fail("markdown heading missing");
  if (results.md.table !== 1) fail("GFM table row missing");
  if (results.md.list !== 2) fail("list items missing");
  step("markdown previewer", results.md);
  await page.screenshot({ path: `${shots}/preview-matrix-md-${STAMP}.png` });

  // 3. csv: upstream's standalone page has **no** csv branch, so `?ext=csv`
  //    must render the `fileError` notice there; the shared dispatcher (chunk
  //    workbench) is where `CSVFileViewer` runs.
  results.csvStandalone = await expect(seeded.ids["table.csv"], "csv", async () => {
    await page.waitForSelector("[data-testid='file-error']", { timeout: 30000 });
    return page.evaluate(
      () => document.querySelector("[data-testid='file-error']").textContent.trim(),
    );
  });
  step("csv on the standalone page", results.csvStandalone);

  await page.goto(`${ORIGIN}/documents/${datasetId}/${seeded.ids["table.csv"]}`, {
    waitUntil: "domcontentloaded",
    timeout: 40000,
  });
  await page.waitForFunction(
    () => document.querySelectorAll("#dpCsv tbody tr").length === 2,
    null,
    { timeout: 30000 },
  );
  results.csv = await page.evaluate(() => ({
    kind: document.querySelector("[data-testid='docpreview-section']").dataset.kind,
    headers: Array.from(document.querySelectorAll("#dpCsv thead th")).map(
      (cell) => cell.textContent,
    ),
    rows: Array.from(document.querySelectorAll("#dpCsv tbody tr")).map((row) =>
      Array.from(row.querySelectorAll("td")).map((cell) => cell.textContent),
    ),
  }));
  if (results.csv.kind !== "csv") fail("csv did not select the csv previewer");
  if (results.csv.headers.join() !== "name,size") fail("csv header row wrong");
  if (results.csv.rows[1][1] !== "-") fail("empty csv cell must render '-'");
  step("csv previewer (chunk workbench)", results.csv);
  await page.screenshot({ path: `${shots}/preview-matrix-csv-${STAMP}.png` });

  // 3b. video: dispatcher-only as well. The upload whitelist has no video
  //     extension (upstream's `CONTENT_TYPE_MAP` has none either), so the branch
  //     is reached the way any non-uploadable type is: a record whose name carries
  //     the extension. Renaming an uploaded document is the supported path, and
  //     the previewer only needs the stored bytes.
  await page.evaluate(
    async ({ datasetId, documentId }) => {
      await fetch(`/api/v1/datasets/${datasetId}/documents/${documentId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: "clip.mp4" }),
      });
    },
    { datasetId, documentId: seeded.ids["notes.txt"] },
  );
  await page.goto(`${ORIGIN}/documents/${datasetId}/${seeded.ids["notes.txt"]}`, {
    waitUntil: "domcontentloaded",
    timeout: 40000,
  });
  await page.waitForFunction(
    () => {
      const video = document.getElementById("dpVideo");
      return video && !video.hidden && (video.src || "").startsWith("blob:");
    },
    null,
    { timeout: 30000 },
  );
  results.video = await page.evaluate(() => {
    const video = document.getElementById("dpVideo");
    return {
      kind: document.querySelector("[data-testid='docpreview-section']").dataset.kind,
      src: video.src.slice(0, 5),
      controls: video.controls,
    };
  });
  if (results.video.kind !== "video") fail("video did not select the video previewer");
  if (!results.video.controls) fail("video element must expose controls");
  step("video previewer (chunk workbench)", results.video);

  // 4. image: `ImagePreviewer` paints the blob object URL.
  results.image = await expect(seeded.ids["pixel.png"], "png", async () => {
    await page.waitForFunction(
      () => {
        const image = document.getElementById("dpImage");
        return image && !image.hidden && image.naturalWidth > 0;
      },
      null,
      { timeout: 30000 },
    );
    return page.evaluate(() => {
      const image = document.getElementById("dpImage");
      return {
        src: image.src.slice(0, 5),
        width: image.naturalWidth,
        height: image.naturalHeight,
        alt: image.alt,
      };
    });
  });
  if (results.image.width !== 2) fail("image did not decode");
  step("image previewer", results.image);

  // 5. spreadsheet: the workbook grid comes from the Rust reader.
  results.xlsx = await expect(seeded.ids["book.xlsx"], "xlsx", async () => {
    await page.waitForFunction(
      () => document.querySelectorAll("#dpGrid tbody tr").length >= 1,
      null,
      { timeout: 30000 },
    );
    return page.evaluate(() => ({
      tabs: Array.from(document.querySelectorAll("[data-testid='dp-sheet-tab']")).map(
        (tab) => tab.textContent,
      ),
      headers: Array.from(document.querySelectorAll("#dpGrid thead th")).map(
        (cell) => cell.textContent,
      ),
      firstRow: Array.from(document.querySelectorAll("#dpGrid tbody tr td")).map(
        (cell) => cell.textContent,
      ),
    }));
  });
  if (results.xlsx.headers.join() !== "name,size") fail("workbook header row wrong");
  step("spreadsheet previewer", results.xlsx);
  await page.screenshot({ path: `${shots}/preview-matrix-xlsx-${STAMP}.png` });

  // 6. slides: per-slide text from the Rust reader.
  results.pptx = await expect(seeded.ids["deck.pptx"], "pptx", async () => {
    await page.waitForFunction(
      () => document.querySelectorAll("[data-testid='dp-slide']").length === 2,
      null,
      { timeout: 30000 },
    );
    return page.evaluate(() =>
      Array.from(document.querySelectorAll("[data-testid='dp-slide']")).map((slide) => ({
        title: slide.querySelector("h3").textContent,
        body: slide.querySelector(".docpreview-slide-body").textContent.trim(),
      })),
    );
  });
  if (!results.pptx[0].body.includes("First slide")) fail("first slide text missing");
  step("slides previewer", results.pptx);
  await page.screenshot({ path: `${shots}/preview-matrix-pptx-${STAMP}.png` });

  // 7. html: upstream `previewHtmlFile` fetches the bytes, wraps them in a Blob
  //    and clicks an anchor **without** a `download` attribute, so the browser
  //    renders the blob in place (it is not a download). The section itself is the
  //    empty `preview-html` marker upstream renders before returning.
  await page.goto(`${ORIGIN}/document/${seeded.ids["notes.txt"]}?ext=html`, {
    waitUntil: "domcontentloaded",
    timeout: 40000,
  });
  // The branch hands the bytes over as soon as the page boots, so the live DOM is
  // already gone; the rendered markup is asserted from the server response and the
  // navigation below proves the script ran.
  const htmlMarkup = await (
    await page.request.get(`${ORIGIN}/document/${seeded.ids["notes.txt"]}?ext=html`)
  ).text();
  const htmlKind = htmlMarkup.includes("data-kind='html'") ? "html" : null;
  const htmlSections = (htmlMarkup.match(/data-testid='preview-html'/g) || []).length;
  await page
    .waitForFunction(() => location.protocol === "blob:", null, { timeout: 20000 })
    .catch(() => {});
  const navigatedToBlob = await page
    .evaluate(() => location.protocol === "blob:")
    .catch(() => false);
  results.html = { kind: htmlKind, sections: htmlSections, navigatedToBlob };
  if (htmlKind !== "html") fail("html branch did not select");
  if (htmlSections !== 1) fail("html branch must render its (empty) section");
  if (!navigatedToBlob) fail("html branch did not hand the bytes to the browser");
  step("html branch", results.html);

  // 8. docx / doc: the pending notice is loud, never a silent blank section.
  results.doc = await expect(seeded.ids["legacy.docx"], "docx", async () => {
    await page.waitForSelector("[data-testid='preview-docx']", { timeout: 30000 });
    return page.evaluate(() => ({
      notice: document.querySelector("[data-testid='file-error']")?.textContent.trim(),
      pending: document.querySelector("[data-testid='dp-pending']")?.textContent.trim(),
    }));
  });
  if (!results.doc.pending) fail("docx branch must state that its previewer is pending");
  step("docx branch", results.doc);

  // 9. unknown extension: the `fileError` notice, not an empty page.
  results.unknown = await expect(seeded.ids["legacy.docx"], "exe", async () => {
    await page.waitForSelector("[data-testid='file-error']", { timeout: 30000 });
    return page.evaluate(
      () => document.querySelector("[data-testid='file-error']").textContent.trim(),
    );
  });
  if (!results.unknown.includes("File error")) fail("unknown type must render the fileError notice");
  step("unknown type", results.unknown);

  // 10. resource=files reads the file route instead of the document route.
  await page.goto(`${ORIGIN}/document/${seeded.fileId}?ext=txt&resource=files`, {
    waitUntil: "domcontentloaded",
    timeout: 40000,
  });
  await page.waitForFunction(
    () => (document.getElementById("dpText")?.textContent || "").includes("preview probe"),
    null,
    { timeout: 30000 },
  );
  results.resource = await page.evaluate(() => ({
    url: window.DP_STATE.url,
    resource: window.DP_STATE.resource,
    text: document.getElementById("dpText").textContent.trim(),
  }));
  if (results.resource.url !== `/api/v1/files/${seeded.fileId}`) fail("files byte source wrong");
  step("resource=files", results.resource);

  // 11. The files page Eye button links at the same contract, and only for the
  //     types upstream's `SupportedPreviewDocumentTypes` lists.
  await page.goto(`${ORIGIN}/files`, { waitUntil: "domcontentloaded", timeout: 40000 });
  await page.waitForSelector("[data-testid='file-preview-link']", { timeout: 30000 });
  results.filesPage = await page.evaluate(() => ({
    links: Array.from(document.querySelectorAll("[data-testid='file-preview-link']")).map(
      (link) => ({ href: link.getAttribute("href"), target: link.getAttribute("target") }),
    ),
    rows: document.querySelectorAll(".file-name").length,
  }));
  const eyeHref = results.filesPage.links.map((link) => link.href).join(" ");
  if (!eyeHref.includes(`?ext=png&resource=files`)) {
    fail("files page Eye link wrong: " + eyeHref);
  }
  if (eyeHref.includes("?ext=txt&resource=files")) {
    fail("txt must not carry an Eye button upstream: " + eyeHref);
  }
  if (results.filesPage.links.some((link) => link.target !== "_blank")) {
    fail("files page Eye link must open a new tab");
  }
  step("files page Eye button", results.filesPage);
  await page.screenshot({ path: `${shots}/preview-matrix-files-${STAMP}.png` });

  results.pageErrors = pageErrors;
  if (pageErrors.length) fail("page errors: " + JSON.stringify(pageErrors));
} catch (error) {
  results.errors.push(String(error && error.message ? error.message : error));
  results.diagnostics = await page
    .evaluate(() => ({
      url: location.href,
      kind: document.querySelector("[data-testid='docpreview-section']")?.dataset.kind,
      toast: document.getElementById("dpToast")?.textContent,
      text: (document.getElementById("dpText")?.textContent || "").slice(0, 80),
    }))
    .catch((diagnosticError) => ({ diagnosticError: String(diagnosticError.message) }));
  console.error("PROBE FAILED:", results.errors[results.errors.length - 1]);
} finally {
  if (datasetId) {
    await page
      .evaluate(async (id) => {
        await fetch("/api/v1/datasets", {
          method: "DELETE",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ ids: [id] }),
        }).catch(() => {});
      }, datasetId)
      .catch(() => {});
  }
}
console.log(JSON.stringify(results, null, 2));
process.exit(results.errors.length ? 1 : 0);
